import tkinter as tk
from tkinter import simpledialog, messagebox

def get_user_input():
    """Ask user for input and return it"""
    try:
        user_input = simpledialog.askstring("Input", "Enter some text:")
        if user_input:
            return user_input
        else:
            return None
    except tk.TclError:
        return None

